class ResourceCollector:
    """系统资源采集器。"""

    def __init__(self, config=None):
        self.config = config
        self._prev_net_io = None
        self._prev_net_time = None
        self._prev_disk_io = None
        self._prev_disk_time = None

        if not _HAS_PSUTIL:
            logger.warning('psutil 未安装，资源监控将使用模拟数据')

    def collect(self):
        """采集一次系统资源快照。

        返回:
            ResourceSnapshot 实例
        """
        if not _HAS_PSUTIL:
            return self._dummy_snapshot()

        try:
            cpu = psutil.cpu_percent(interval=0.5)
            vm = psutil.virtual_memory()
            mem = vm.percent

            # 磁盘使用率（根目录）
            disk = None
            try:
                disk = psutil.disk_usage('/').percent
            except (OSError, PermissionError):
                pass

            # 网络速率
            net_rx, net_tx = self._network_speed()

            # 内存绝对值
            memory_used = vm.used
            memory_total = vm.total

            # 系统负载
            load_avg_1 = load_avg_5 = load_avg_15 = None
            try:
                la = psutil.getloadavg()
                load_avg_1, load_avg_5, load_avg_15 = la[0], la[1], la[2]
            except (OSError, AttributeError):
                pass

            # 磁盘 IO 速率（bytes/s）
            disk_read, disk_write = self._disk_io_speed()
            disk_read_count = disk_write_count = None
            # 注意：disk_io_counters 的 read_count/write_count 也是累计值
            # 如果需要速率，也需要做差值计算（此处暂不处理）

            # 进程信息
            process_count = None
            top_processes = None
            try:
                procs = psutil.process_iter(['pid', 'name', 'cpu_percent', 'memory_percent'])
                process_count = len(list(procs))
                # Top 5 进程（按 CPU 使用率）
                proc_list = []
                for p in psutil.process_iter(['pid', 'name', 'cpu_percent', 'memory_percent']):
                    try:
                        proc_list.append(p.info)
                    except (psutil.NoSuchProcess, psutil.AccessDenied):
                        pass
                proc_list.sort(key=lambda x: x.get('cpu_percent') or 0, reverse=True)
                top_processes = proc_list[:5]
            except (psutil.AccessDenied, Exception):
                pass

            snapshot = ResourceSnapshot(
                cpu=cpu, memory=mem, disk=disk,
                network_rx=net_rx, network_tx=net_tx,
                memory_used=memory_used, memory_total=memory_total,
                load_avg_1=load_avg_1, load_avg_5=load_avg_5, load_avg_15=load_avg_15,
                disk_read=disk_read, disk_write=disk_write,
                disk_read_count=disk_read_count, disk_write_count=disk_write_count,
                process_count=process_count, top_processes=top_processes)

            logger.debug('资源采集: cpu=%.1f%% mem=%.1f%% load=%.2f procs=%s',
                         cpu, mem, load_avg_1 or 0, process_count or 0)
            return snapshot

        except Exception:
            logger.debug('资源采集失败', exc_info=True)
            return self._dummy_snapshot()

    def _network_speed(self):
        """计算网络收发速率（bytes/s）。"""
        try:
            net_io = psutil.net_io_counters()
            now = time.time()
            if self._prev_net_io and self._prev_net_time:
                dt = now - self._prev_net_time
                if dt > 0:
                    rx_speed = (net_io.bytes_recv - self._prev_net_io.bytes_recv) / dt
                    tx_speed = (net_io.bytes_sent - self._prev_net_io.bytes_sent) / dt
                    self._prev_net_io = net_io
                    self._prev_net_time = now
                    return round(rx_speed, 1), round(tx_speed, 1)
            self._prev_net_io = net_io
            self._prev_net_time = now
        except Exception:
            pass
        return None, None

    def _disk_io_speed(self):
        """计算磁盘 IO 速率（bytes/s）。"""
        try:
            dio = psutil.disk_io_counters()
            if not dio:
                return None, None
            now = time.time()
            if self._prev_disk_io and self._prev_disk_time:
                dt = now - self._prev_disk_time
                if dt > 0:
                    read_speed = (dio.read_bytes - self._prev_disk_io.read_bytes) / dt
                    write_speed = (dio.write_bytes - self._prev_disk_io.write_bytes) / dt
                    self._prev_disk_io = dio
                    self._prev_disk_time = now
                    return round(read_speed, 1), round(write_speed, 1)
            self._prev_disk_io = dio
            self._prev_disk_time = now
        except Exception:
            pass
        return None, None

    def _dummy_snapshot(self):
        """模拟数据（psutil 不可用时）。"""
        return ResourceSnapshot(cpu=0.0, memory=0.0)
